PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS metadata (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, payload TEXT NOT NULL CHECK(json_valid(payload)));
CREATE TABLE IF NOT EXISTS employees (id TEXT PRIMARY KEY, payload TEXT NOT NULL CHECK(json_valid(payload)));
CREATE TABLE IF NOT EXISTS appraisals (id TEXT PRIMARY KEY, employee_id TEXT NOT NULL REFERENCES employees(id), version INTEGER NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)));
CREATE TABLE IF NOT EXISTS finalisations (id TEXT PRIMARY KEY, appraisal_id TEXT NOT NULL REFERENCES appraisals(id), version INTEGER NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), UNIQUE(appraisal_id,version));
CREATE TABLE IF NOT EXISTS audit_events (id TEXT PRIMARY KEY, at TEXT NOT NULL, actor_id TEXT NOT NULL, entity_id TEXT NOT NULL, action TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)));
CREATE TRIGGER IF NOT EXISTS audit_no_update BEFORE UPDATE ON audit_events BEGIN SELECT RAISE(ABORT, 'Audit events are immutable'); END;
CREATE TRIGGER IF NOT EXISTS audit_no_delete BEFORE DELETE ON audit_events BEGIN SELECT RAISE(ABORT, 'Audit events are immutable'); END;
CREATE TRIGGER IF NOT EXISTS finalisations_no_update BEFORE UPDATE ON finalisations BEGIN SELECT RAISE(ABORT, 'Finalisations are immutable'); END;
CREATE TRIGGER IF NOT EXISTS finalisations_no_delete BEFORE DELETE ON finalisations BEGIN SELECT RAISE(ABORT, 'Finalisations are immutable'); END;
CREATE INDEX IF NOT EXISTS appraisal_employee ON appraisals(employee_id);
CREATE INDEX IF NOT EXISTS audit_entity_time ON audit_events(entity_id, at);
